#!/usr/bin/env node
/**
 * Portfolio Resume & Projects update. Uses only Node.js built-in modules.
 * Run from the existing project folder:
 *   node "C:\\Users\\YOUR_NAME\\Downloads\\Update_Portfolio.mjs"
 * Optional: --project "E:\\Portfolio\\abdur-rahman-portfolio"
 * Preview: --dry-run    Copy only: --skip-checks
 * Restore: --rollback "PATH_PRINTED_AS_BACKUP"
 * Personal profile settings, the portrait, PDF, package files, and installed
 * dependencies are preserved. Every changed file is backed up first.
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

const UPDATE = {"id":"resume-projects-2026-11-07-v1","title":"Resume & Projects portfolio update","files":[{"path":"src/app/App.tsx","type":"file","sha256":"f7f8bb7f7e47bbbc53d9a8a55f0c4b012fa27ca1287db0fdb019d14b26ea30cf","data":""},{"path":"src/app/components/Navigation.tsx","type":"file","sha256":"f4a57764187d7c0ce71e60202da4203c53dfbdecfc207fbc08f10d3aa425aa05","data":""},{"path":"src/app/components/Projects.tsx","type":"file","sha256":"45d6f228287439b08dd13296cec09c2171dc173ed5d75481fa3577e2d9ee29d8","data":""},{"path":"src/app/components/TechStack.tsx","type":"file","sha256":"fd29f14d9ce906a11e2da3ff90928931f84bbe19bcc51019cdd7403ad9465d25","data":""},{"path":"src/app/components/PortfolioExtras.tsx","type":"file","sha256":"42b0c4934a3d61dbd26ec72578acd718ce91923fa383d05d625dfba4779a3a52","data":""},{"path":"src/app/components/SkillIcon.tsx","type":"file","sha256":"2d7f2bb2fb730d798ee91485871615cb525a5a670c9f37e8f0ba15c5b062d828","data":""},{"path":"src/app/components/ResumeSections.tsx","type":"file","sha256":"ef14a832ccfb9eb8b30133f487d81fbb699e0022cd65e308486a4bdfade11103","data":""},{"path":"src/app/data/resume.ts","type":"file","sha256":"f3b39738419b09fb3231900142272252e42abfffffd70b81a5793f7025c41f81","data":""},{"path":"src/app/pages/Resume.tsx","type":"file","sha256":"f2659331c93013d4e6fae382c1c746a9e871dcde1d60b9fab05dcb54d1afd96f","data":""},{"path":"src/app/lib/utils.ts","type":"file","sha256":"e6c49ea66e5ad8dafcb7a75cb9951158015ff99236d7c286775c8af2e75be3cb","data":""},{"path":"tests/utils.test.ts","type":"file","sha256":"062e8d667392881c5aa5d8580d7910ecd3114da89c10b05e0d71cffec3ac861e","data":""},{"path":"qa/responsive.html","type":"file","sha256":"5d18199ca319a02a55040a60941e148a67ee6455d16b674be376a961a4641229","data":""},{"path":"README.md","type":"file","sha256":"c8c020de64a3a5778dcf3aa95f21c6052e48b10f694a901ab4f435808636f1e2","data":""},{"path":"START_HERE_WINDOWS.md","type":"file","sha256":"014976e32eba3b71aeb3b8ee0e467c6f711afeb56c37599bd66cd553ea19ec83","data":""},{"path":"DEPLOYMENT.md","type":"file","sha256":"afd8a4a8472e72d1037134a439a8ec90f713a687226694465152e61c9c914f65","data":""},{"path":"VALIDATION.md","type":"file","sha256":"d3887cb573a3921fe51c27633fc3ad78b4baa21dbd7816bf69fca1a6485f6524","data":""},{"path":"UPDATE_RESUME_PROJECTS.md","type":"file","sha256":"3bad8203855165534537d47ec6093f2535a3f7d37cdd86965b9f1622610ca13d","data":""},{"path":"public/images/aiub-logo.png","type":"file","sha256":"ba4d4cf9eb71b05068c9408a063193acc6086c4fc3e1198953bbec951da9228b","data":""},{"path":"src/app/components/Hero.tsx","type":"replace-text","edits":[{"from":"#/portfolio","to":"#/projects"}]}]};
const args = process.argv.slice(2);
const has = flag => args.includes(flag);
const value = flag => { const i = args.indexOf(flag); if (i < 0) return undefined; if (!args[i + 1] || args[i + 1].startsWith('--')) throw new Error(`Missing value after ${flag}`); return args[i + 1]; };
const hash = data => crypto.createHash('sha256').update(data).digest('hex');
const readIfFile = file => fs.existsSync(file) ? fs.readFileSync(file) : null;

function safePath(root, relative) {
  if (typeof relative !== 'string' || path.isAbsolute(relative) || relative.split(/[\\/]/).includes('..')) throw new Error('Invalid update path.');
  const target = path.resolve(root, relative);
  if (!target.startsWith(root + path.sep)) throw new Error('Update path leaves the project folder.');
  let current = root;
  for (const part of path.relative(root, target).split(path.sep)) {
    current = path.join(current, part);
    if (fs.existsSync(current) && fs.lstatSync(current).isSymbolicLink()) throw new Error(`Refusing to overwrite a symbolic link: ${relative}`);
  }
  return target;
}

function writeFile(file, bytes) { fs.mkdirSync(path.dirname(file), {recursive:true}); fs.writeFileSync(file, bytes); }

function runChecks(root, pkg) {
  for (const task of ['typecheck', 'test', 'build']) {
    if (!pkg.scripts?.[task]) continue;
    console.log(`\nRunning npm run ${task} ...`);
    const command = process.platform === 'win32' ? (process.env.ComSpec || 'cmd.exe') : 'npm';
    const commandArgs = process.platform === 'win32' ? ['/d','/s','/c',`npm.cmd run ${task}`] : ['run', task];
    const result = spawnSync(command, commandArgs, {cwd:root, stdio:'inherit', env:process.env});
    if (result.error) throw result.error;
    if (result.status !== 0) throw new Error(`npm run ${task} did not pass (exit ${result.status}).`);
  }
}

function restore(root, backup, receipt, verifyCurrent) {
  if (verifyCurrent) {
    for (const entry of receipt.files) {
      const current = readIfFile(safePath(root, entry.path));
      if (!current || hash(current) !== entry.afterHash) throw new Error(`Cannot roll back automatically because this file changed after the update: ${entry.path}. The original remains in the backup folder.`);
    }
  }
  for (const entry of receipt.files) {
    const target = safePath(root, entry.path);
    if (entry.existed) {
      const bytes = fs.readFileSync(safePath(backup, entry.path));
      if (hash(bytes) !== entry.beforeHash) throw new Error(`Backup integrity check failed: ${entry.path}`);
      writeFile(target, bytes);
    } else if (fs.existsSync(target)) fs.unlinkSync(target);
  }
}

function main() {
  if (has('--help')) {
    console.log('Run this file with Node.js from your existing portfolio folder.\nOptional: --project PATH, --dry-run, --skip-checks, --rollback BACKUP_FOLDER');
    return;
  }
  const rollbackPath = value('--rollback');
  let receipt, backup;
  if (rollbackPath) {
    backup = fs.realpathSync(path.resolve(rollbackPath));
    receipt = JSON.parse(fs.readFileSync(path.join(backup, 'update-backup.json'), 'utf8'));
    if (receipt.updateId !== UPDATE.id || !Array.isArray(receipt.files)) throw new Error('This is not a backup from this update.');
    if (receipt.rolledBackAt) { console.log('This backup has already been restored.'); return; }
  }
  const root = fs.realpathSync(path.resolve(value('--project') || receipt?.projectRoot || process.cwd()));
  const packagePath = path.join(root, 'package.json');
  if (!fs.existsSync(packagePath) || !fs.existsSync(path.join(root, 'src/app/data/portfolio.ts'))) throw new Error('Open the terminal in your existing portfolio folder (the one containing package.json), or pass --project "YOUR_FOLDER".');
  const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
  if (!pkg.scripts?.build || !fs.existsSync(path.join(root, 'src/app/App.tsx'))) throw new Error('The selected folder is not the expected React portfolio project.');
  if (!has('--skip-checks') && !has('--dry-run') && !fs.existsSync(path.join(root, 'node_modules'))) throw new Error('This folder has no installed dependencies. Choose your existing configured project, or use --skip-checks to copy files without running checks.');

  if (receipt) {
    if (fs.realpathSync(receipt.projectRoot) !== root) throw new Error('The backup belongs to a different project folder.');
    if (has('--dry-run')) { console.log(`Would restore ${receipt.files.length} files in ${root}`); return; }
    restore(root, backup, receipt, true);
    receipt.rolledBackAt = new Date().toISOString();
    fs.writeFileSync(path.join(backup, 'update-backup.json'), JSON.stringify(receipt,null,2));
    if (!has('--skip-checks')) runChecks(root,pkg);
    console.log('\nRestored the project files from this backup.');
    return;
  }

  const protectedPaths = new Set(['package.json','package-lock.json','src/app/data/portfolio.ts','public/images/profile.png','public/resume/Abdur-Rahman-CV.pdf']);
  const changes = [];
  for (const entry of UPDATE.files) {
    if (protectedPaths.has(entry.path) || entry.path.startsWith('node_modules/')) throw new Error(`Protected file in update: ${entry.path}`);
    const target = safePath(root, entry.path);
    const before = readIfFile(target);
    let after;
    if (entry.type === 'replace-text') {
      if (!before) continue;
      let text = before.toString('utf8');
      for (const edit of entry.edits) text = text.split(edit.from).join(edit.to);
      after = Buffer.from(text,'utf8');
    } else {
      after = Buffer.from(entry.data,'base64');
      if (hash(after) !== entry.sha256) throw new Error(`Update payload integrity check failed: ${entry.path}`);
    }
    if (before && hash(before) === hash(after)) continue;
    changes.push({path:entry.path,target,before,after});
  }
  if (!changes.length) { console.log('Your project already has this update. No files changed.'); return; }
  console.log(`\n${UPDATE.title}\nProject: ${root}\n\nFiles to update:`);
  for (const entry of changes) console.log(`  ${entry.before ? 'Update' : 'Add'}  ${entry.path}`);
  if (has('--dry-run')) { console.log('\nDry run complete. No files changed.'); return; }

  const stamp = new Date().toISOString().replace(/[:.]/g,'-');
  backup = path.join(root,'portfolio-update-backups',`${UPDATE.id}-${stamp}`);
  fs.mkdirSync(backup,{recursive:true});
  receipt = {updateId:UPDATE.id,projectRoot:root,createdAt:new Date().toISOString(),files:changes.map(entry=>({path:entry.path,existed:!!entry.before,beforeHash:entry.before?hash(entry.before):null,afterHash:hash(entry.after)}))};
  for (const entry of changes) if (entry.before) writeFile(safePath(backup,entry.path),entry.before);
  fs.writeFileSync(path.join(backup,'update-backup.json'),JSON.stringify(receipt,null,2));
  console.log(`\nBackup: ${backup}`);
  try {
    for (const entry of changes) writeFile(entry.target,entry.after);
    if (!has('--skip-checks')) runChecks(root,pkg);
    receipt.completedAt = new Date().toISOString();
    fs.writeFileSync(path.join(backup,'update-backup.json'),JSON.stringify(receipt,null,2));
  } catch (error) {
    restore(root,backup,receipt,false);
    receipt.rolledBackAt = new Date().toISOString();
    fs.writeFileSync(path.join(backup,'update-backup.json'),JSON.stringify(receipt,null,2));
    console.error('\nThe update did not complete. Original project files were restored.');
    try { if (!has('--skip-checks')) runChecks(root,pkg); } catch { console.error('Check the reported errors before restarting the website.'); }
    throw error;
  }
  console.log('\nUpdate complete. Your profile settings, portrait, resume PDF, and installed dependencies were preserved.');
  console.log('Start the website with: npm.cmd run dev  (Windows) or npm run dev  (macOS/Linux).');
  console.log(`To restore the previous files:\nnode "${process.argv[1]}" --rollback "${backup}"`);
}

try { main(); } catch (error) { console.error(`\nUpdate error: ${error.message}`); process.exitCode = 1; }
